contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept any receiver and amount; the test will try calling sendTo from this contract.
    function run(address receiver, uint256 amount) public payable {
        require(true);

        // Ensure this test contract has enough balance if a non-reverting call were possible.
        // This is needed so that calling would have had funds to send; avoid false positives due to lack of funds.
        if (amount > 0) {
            require(address(this).balance >= amount);
        }

        // Read c's balance before the call.
        uint256 before = address(c).balance;

        // Attempt the call and catch whether it reverted.
        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = address(c).balance;

        // General rule: because InvMutTest is not the deployer/owner, any attempt to call sendTo must revert;
        // when it reverts, c's balance must be unchanged. If the call didn't revert (which would imply this
        // contract is owner), then c's balance must have decreased by at most amount (it could be equal if transfer failed),
        // but we assert the primary security property: calls from this caller revert and do not change balance.
        assert(reverted && after == before);
    }

    // allow receiving Ether if needed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try calling sendTo; this contract is not the original deployer of c, so the call should revert
    // and c's balance must remain unchanged when it reverts.
    function run(address receiver, uint256 amount) public payable {
        require(true);

        // If a non-reverting call would send Ether, make sure this test contract has enough balance to cover any checks
        if (amount > 0) {
            require(address(this).balance >= amount);
        }

        // observe balance before
        uint256 balBefore = address(c).balance;

        bool didRevert;
        try c.sendTo(receiver, amount) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // observe balance after
        uint256 balAfter = address(c).balance;

        // General rule: because InvMutTest did not deploy c, sendTo must revert and c's balance must be unchanged when it reverts.
        assert(didRevert && balAfter == balBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: receiver address and amount to send from c to receiver
    function run(address payable receiver, uint256 amount) public payable {
        require(receiver != address(0)); // avoid trivial zero-address requirement inside C

        // Observe balances before the call
        uint256 cBalBefore = address(c).balance;
        uint256 recvBalBefore = receiver.balance;

        // If a successful call would transfer Ether from c, ensure this test has no need to send Ether.
        // (We don't send value to c here; c was deployed fresh by the checker.)

        bool didRevert;
        try c.sendTo(receiver, amount) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        uint256 cBalAfter = address(c).balance;
        uint256 recvBalAfter = receiver.balance;

        // General rule: whenever sendTo does NOT revert, c's balance must decrease by exactly amount
        // and the receiver's balance must increase by exactly amount.
        assert(didRevert || (cBalBefore == cBalAfter + amount && recvBalAfter == recvBalBefore + amount));
    }

    receive() external payable {}
}

